-- Import des courriers arrivées 2010
-- Source : 2010.xlsx (feuille 2010).
--
-- Correspondance Excel -> table arrivees (formulaire arrivee/create.vue)
--   N°                -> txt_numdordre (00001/jj-mm-aaaa) et txt_numcourier
--   DATE CREATION     -> dt_datearrivee et dt_datecourier
--   PRENOMS + NOM     -> txt_prenomNom et txt_expediteur
--   DESIGNATIONS      -> txt_objet (libellé d'origine)
--   DESIGNATIONS      -> txt_designation (liste designationsParCategorie)
--   designation retenue -> txt_categorie
--   TF EN Dakar Gorée -> txt_numTitreMere si un TF Grand Dakar est aussi présent, sinon txt_numTitreFoncier
--   N° TF GRAND DAKAR -> txt_numTitreFoncier
--   N° LOT            -> txt_numLot
--   SITUATION         -> txt_lotissement
--   AGENTS TRAITEURS  -> txt_agenttraiteur
--   OBSERVATIONS      -> txt_observation
--   CATEGORIES        -> ignorée (toujours Demande SERVICES) ; la catégorie vient de la désignation
--   référence formulaire -> « <N°> du jj-mm-aaaa »
--   NICAD cité dans l'objet -> txt_NICAD
--
-- Champs obligatoires absents du classeur :
--   txt_typecourrier = BE si l'objet commence par « BE », sinon Individuel
--   txt_nombrepiece  = 1
--   expéditeur ou agent vide -> Non renseigné
-- Références en doublon : suffixe [n° d'ordre].
-- N° d'arrivée en doublon : suffixe -2, -3…
-- Dates d'arrivée illisibles reconstituées sur la ligne voisine : 0
-- Lignes importées : 2849
-- Lignes non importées :
--   ligne Excel 2840 : N° d'arrivée absent (Cheikh Tidiane GUAYE / Demande de Régularisation)
--
-- Répartition des catégories :
--    2759  Demande SERVICES
--      64  Information
--      16  Convocation - Invitation
--       8  Réclamation - Signalement
--       2  Réquisition - Instruction
-- Désignations :
--    1396  Morcellements
--     639  Autorisation de construction
--     270  Demande de Cession définitive
--     191  Demande de Régularisation par voie de Bail
--      74  Demande de terrain/Echange
--      64  Demande de délimitation
--      38  Litiges
--      19  Demande d'états des lieux
--      17  Duplication de CIC
--      14  Autorisation de lotir
--      13  Autres
--      13  Circulaire
--      10  Note de service
--      10  Décision - Arrêté
--      10  Réquisition d'immatriculation
--       9  Formation
--       8  Plainte
--       7  Rapport
--       7  Document administratif
--       7  Réunion
--       5  Demande de Titre foncier
--       5  Demande de situation foncière
--       4  Demande d'extraits de plan
--       4  Demande d'évaluation
--       4  Réceptions de lotissements
--       4  Demande d'attestation du Cadastre
--       2  Instruction à suivre
--       2  PV - Compte - rendu
--       2  Lettre
--       1  Tribunal

SET NAMES utf8mb4;

-- Certains N° TF du classeur dépassent 25 caractères (listes de titres).
ALTER TABLE `arrivees`
  MODIFY `txt_numTitreFoncier` VARCHAR(255) NULL,
  MODIFY `txt_numTitreMere` VARCHAR(255) NULL;

START TRANSACTION;









COMMIT;
